  VALUES 
    (387::BIGINT, 'Nos cubrió como por un mes el grupo de TEM I. El mae sabe un montón y explica mucho sobre las aplicaciones del curso, pero prácticamente no ve ni hace ejercicios, además de que va muy rápido. Explica bien, pero podría ser más claro.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2026-10-16T00:00:00+00:00'::TIMESTAMPTZ, '102c0f06d5df46999ffa637d80fe4c00ccb659ccbbca6b2ab9c6be9f87e83e65'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'Alabado sea Sergio Cristo redendor de Electronica'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2026-04-30T00:00:00+00:00'::TIMESTAMPTZ, 'dfea28330e7f47e3d3c58096c896727af5b8b0dbee96c3c8d555414b03232405'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'Es muy buen profe y ayuda bastante, y trata de usar otros recursos para explicar, el problema es el curso la materia es demasiado densa, es muy pesado el curso, el hasta da 5 semanas de repaso antes de entrar en materia de clase y la rubrica horrible, 90% exámenes y apenas son dos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'c947b7f19a804cd6d8b10eacdbd73bb71af03ae5e227accccb08193edc78fb7d'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'El curso lo hicieron extremadamente duro, ya que en los años pasados lo regalaban. El profe es bueno, pero califica bastante fuerte y los ejercicios que hace junto a William son difíciles. Es un curso que es bastante denso en materia por lo que hay que doblar esfuerzos para pasar a la primera'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '74381f942826da2d54b89ef001f2f65cda990603639eac35315854b007a9fad5'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'Muy buen profe en realidad a este punto de la carrera uno no busca complicarse y el profe es bastante flexible con las fechas de entrega, además da buena retroalimentación y responde dudas de buena forma'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '99d8f9ffcef8ecccb45737c7c643015c33b9d37f7a6db99ba01bdcf28d664d9f'::TEXT, ARRAY[1326]::BIGINT[]),
    (387::BIGINT, 'Excelente profe, atiende muy bien a las consultas y busca ayudarlo a uno a entender'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '50af6a3a2d43ab45ed1dd0078027a51b3e950a6a075bc6ffc39f84a22f69a200'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Terrible, todos los comentarios esperando revisión? Enserio? Este profe se pierde con sus drones y ya. Las clases las da como para postgrados no sé, va volado. Y si uno tiene una duda lo trata de ignorante. Manda ... si quiere sufrir en el semestre con estrés por este profe, dele matricule con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-28T00:00:00+00:00'::TIMESTAMPTZ, '19c519aee64eb55e8c39d4f4d39d8b90e3074b0f7b2924c60a63b6a01d4e65dd'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'taller de drones..........sea lolo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '8750683e932265d787c0f67333c985ea1a8382def743922e40edd7486db1bad6'::TEXT, ARRAY[1326]::BIGINT[]),
    (387::BIGINT, 'Terrible, todos los comentarios esperando revisión? Enserio? Este profe se pierde con sus drones y ya. Las clases las da como para postgrados no sé, va volado. Y si uno tiene una duda lo trata de ignorante. Manda ... si quiere sufrir en el semestre con estrés por este profe, dele matricule con él'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '008fa670e8e55d0f0ab2d0b1e1aa5005dcecc8e1fbdab72dd77e2d8cf25cd8f1'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'piensa que está dando maestría'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '188a397ef49b59bce02a70d58dfe631658ea500dea57004eddc02d23c6898303'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Es un profe que se toma el tiempo de revisar detalladamente pero de igual manera se toma demasiado tiempo para ayudar, por lo que se aprende mucho con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '35a868e55074a499df5187d3df8053bb8e0e3d23a16747cbf13b3b4ad150d807'::TEXT, ARRAY[1326]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-04-03T00:00:00+00:00'::TIMESTAMPTZ, '821d94f3c99e81eba6a18d4d988fc9e6f4884b56e11a9123829b94382623d00f'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '41687bc40447f186954fe23ed664ad4a3ad2ddae23222f9caf54aaecb864536a'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Se basa en presentaciones para dar la clase, sin embargo el curso en sí necesita más esfuerzo del estudiante. Siempre deja algún trabajo de puntos extra que sirven para estudiar (Exámenes de semestres pasados).'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5d965498707cd9a95b6ae549cb38a5ed007b2ae668bd4b0de030f27ce95fb163'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, '6d02e24e27135092a923e183a6abba0af6d0f355249ae67783fd103662aec49f'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-06T00:00:00+00:00'::TIMESTAMPTZ, '29e5a0262a4774dccdb02ea3bf8ee8cfe6b0d212314b3c68d3311353e705161f'::TEXT, ARRAY[1390, 1374, 3034, 1280, 3033, 1271]::BIGINT[]),
    (387::BIGINT, 'Malo. Se auto — califica y borra comentarios. Se la tira de conocedor y todos saben que es un solamente vasallo de Rimolo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-14T00:00:00+00:00'::TIMESTAMPTZ, '57d1c324b2dca771e2408c5840bcb6ebcc4de2a4a963a3176903ab4062654ace'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Clases densas pero es natural del curso, pero nada del otro mundo... De igual manera hay mucho material de practica y examenes viejos, el profesor es sumamente bueno se aprende la verdad recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4dee2cd490d1972ad66104df79a0ca656702eaf2c641c7f12f4ae96372e36815'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'En la clase da solo teoría, por lo que hace muy pocos ejemplos en clase. Lo que tiene que hacer es estudiar del libro y hacer exámenes viejos y luego ir a consulta con las dudas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2a254b10e67dfb94cf71cf84ce58f5ce7b96a36f9bc87648412406e8a3c58e3'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Las clases son malas, pero si busca al profe por aparte es demasiado bueno, siempre tiene buen ánimo para atenderlo a uno. Lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b4883372b544674fec1e9cc51a4f2172358d236238ad78b7b28f8fc7c36e511b'::TEXT, ARRAY[1265]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '74c81114747ce71e1ab6a8c1cea3c25040c19b444fbecc219966afcbdec630ec'::TEXT, ARRAY[1363]::BIGINT[]),
    (387::BIGINT, 'Excelente profe, es pura vida. No regala el curso, explica bien y está al nivel del curso. Se preocupa por dejar claro los temas (verano). Las evaluaciones son ajustadas al nivel que exige el curso, nada extravagante o raro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6d5c9fef3d1d9d60f94584e8b01122f33b6742dca1d7342c52398c3664d61ad8'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'El mejor profe para llevar CA, excelentes clases, califica justo y super atento en consulta. No resuelve mucho en clase, pero da mucho material de apoyo y en consulta ayuda a resolverlo. Vaya a consulta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '530678592f621c2fe201795494d6603eac4877c5559fab18a8aa0e89bf38f2b2'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Califica de manera justa, hace las clases entretenidas, le despiera interes por la carrera'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '099e729fe0a41fe2cfd26bfc5fcd7751e3158f8ce5c6c8884a8db820acc35993'::TEXT, ARRAY[1294]::BIGINT[]),
    (387::BIGINT, 'No matricule CA si no es con él. La materia es difícil, pero el profe siempre está dispuesto a ayudar en consulta. Deja material de apoyo y prácticas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-01-20T00:00:00+00:00'::TIMESTAMPTZ, '40ccdf79e43f7db17c20472a042d9887632eed6366cc273ad4a6160b591f2b16'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Es EL profesor para llevar CA explica toda la materia y se procupa por que quede muy claro. Siempre busca motivar al estudiante, es justo para revisar y siempre ayuda mucho en consulta. Las clases son muy pesadas pero esa es la naturaleza del curso los chistes la aligeran. Se sufre pero se pasa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-09T00:00:00+00:00'::TIMESTAMPTZ, '03bf2e7b825e3aa9873f847733157e0c3f3fb27101cd8354d4122718de9795e3'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Un buen profe, no pierde tiempo y realmente explica y enseña como debe ser. La materia es pesada, pero él logra hacer las clases un poco más ligeras con sus chistes. Muy recomendado, se aprende y eso es muy importante en CA.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'dd2af82400943438eb49967a0318c71ce78113a1f66819b39e99f0b75ede88de'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Es un profe muy recomendado, vaya a consulta siempre que pueda, las clases son muy amenas pasa haciendo chistes todo el rato, califica bien no es injusto. Las partes del examen que él hace son las mas duras.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'ce993801d36c437b75a4818f360bba4e424354cf4b5530a4137eade7139ac70c'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Muy buen profe trata de ayudar con las dudas que uno tenga y sabe mucho, los proyectos son interesantes, lo unico aguevado son los cuestionarios previos e informes todas las semanas pero en general es bueno.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'f5382e2dd0c4194ac93cdbd25ed6aca912ad164bcad627fd03b661fbc2e8eb63'::TEXT, ARRAY[1363]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '87a8b0ca65b3e5160ca6a923d73067137b0e593e656ab8b1ad0537c59d39fa8d'::TEXT, ARRAY[1265]::BIGINT[]),
    (387::BIGINT, 'Excelente profesor, no duden en llevar el curso con el, el mejor tranquilos hagan su mejor esfuerzo y pónganle. se sufre pero se pasa.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2017-04-01T00:00:00+00:00'::TIMESTAMPTZ, '5c70bcd8c09424cfdc113df2a0b35e66f8c6ff02f6d3630dc010130d6f243cea'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Explica muy bien.Ayuda mucho, refiriéndose a material y tips para que uno salga bien, también atiende cualquier duda. Se ve interesado en que el estudiante aprenda. Enfocado en que entendamos el por qué y le veamos lógica. La materia es MUCHA, por lo que hace pocos ejercicios.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '84941468e08a789fb7560848adb24e4159ffc46d0f82d75ac15a709cee33c438'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Este profesor es muy bueno, entiende los problemas de los estudiantes (puesto que él fue uno hace poco tiempo).Sin embargo el problema es que se dedico a exponer el Alexander-Sadiku todas las clases y no hizo ejemplos que en realidad ayuden para los examenes. Lo bueno es que casi que regala el curso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3b4c560d0e2e788d51c8aa271465f6998f75563c2c0dc9633637182d95231e88'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Yo lo considero un buen profe, que de verdad se entrega y le gusta lo que hacen, es muy atento con los estudiantes y le importa que uno aprenda, todavía le faltan cosas por mejorar debido a que es nuevo, pero tiene mucho futuro en la docencia universitaria.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '20db772cad54654a8ba3c2eaa2d2a4575be11e20d9cf9fac6e3508a13221aeed'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-08-23T00:00:00+00:00'::TIMESTAMPTZ, '23b0218454b973aad6c536f716e8d3f30f02ab189b2f8fb77d9080db653902ce'::TEXT, ARRAY[1262]::BIGINT[]),
    (387::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2016-08-21T00:00:00+00:00'::TIMESTAMPTZ, '53f749b6ea66a623b639b4b1d162f6230f075c8405c7161dc737331334fe5a8a'::TEXT, ARRAY[1262]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
